<?php require_once 'config.php';require_role('trainer','admin');$u=current_user();$pageTitle='Trainer studio';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='create_course'){$title=trim($_POST['title']??'');$category=trim($_POST['category']??'General');$description=trim($_POST['description']??'');$icon=trim($_POST['icon']??'✦');$status=($_POST['status']??'draft')==='published'?'published':'draft';if($title===''||$description==='')$errors[]='Course title and description are required.';else{$s=db()->prepare('INSERT INTO courses(title,category,description,icon,trainer_id,status) VALUES(?,?,?,?,?,?)');$s->execute([$title,$category,$description,$icon,$u['id'],$status]);flash('Course created successfully.');redirect('trainer.php');}}elseif($action==='add_resource'){$courseId=(int)($_POST['course_id']??0);$title=trim($_POST['resource_title']??'');$type=trim($_POST['resource_type']??'Link');$url=trim($_POST['url']??'');$s=db()->prepare('SELECT id FROM courses WHERE id=? AND (trainer_id=? OR ?="admin")');$s->execute([$courseId,$u['id'],$u['role']]);if(!$s->fetch()||$title===''||!filter_var($url,FILTER_VALIDATE_URL))$errors[]='Choose a course, enter a resource title and a valid URL.';else{$s=db()->prepare('INSERT INTO resources(course_id,title,resource_type,url,created_by) VALUES(?,?,?,?,?)');$s->execute([$courseId,$title,$type,$url,$u['id']]);flash('Learning resource added.');redirect('trainer.php');}}elseif($action==='add_assessment'){$courseId=(int)($_POST['course_id']??0);$title=trim($_POST['assessment_title']??'');$marks=max(1,(int)($_POST['total_marks']??10));$s=db()->prepare('SELECT id FROM courses WHERE id=? AND (trainer_id=? OR ?="admin")');$s->execute([$courseId,$u['id'],$u['role']]);if(!$s->fetch()||$title==='')$errors[]='Choose a course and enter an assessment title.';else{$s=db()->prepare('INSERT INTO assessments(course_id,title,total_marks,question_count,created_by) VALUES(?,?,?,?,?)');$s->execute([$courseId,$title,$marks,0,$u['id']]);flash('Assessment created. Add questions from the assessment page.');redirect('trainer.php');}}}
if($u['role']==='admin')$courses=db()->query('SELECT c.*,u.name trainer_name FROM courses c LEFT JOIN users u ON c.trainer_id=u.id ORDER BY c.created_at DESC')->fetchAll();else{$s=db()->prepare('SELECT * FROM courses WHERE trainer_id=? ORDER BY created_at DESC');$s->execute([$u['id']]);$courses=$s->fetchAll();}$s=db()->prepare('SELECT COUNT(*) FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE c.trainer_id=?');$s->execute([$u['id']]);$learners=(int)$s->fetchColumn();require 'includes/header.php'; ?>
<section class="dashboard-welcome"><div><span class="eyebrow">TRAINER WORKSPACE</span><h1>Build learning that <em>matters.</em></h1><p>Create courses, share learning resources and prepare assessments for your trainees.</p></div><a href="#createCourse" class="btn btn-primary">+ Create course</a></section><section class="stats-grid"><div class="stat-card"><span class="stat-icon blue">▤</span><span>Your courses</span><strong><?= count($courses) ?></strong><small>Drafts and published paths</small></div><div class="stat-card"><span class="stat-icon green">♙</span><span>Course enrollments</span><strong><?= $learners ?></strong><small>Learners across your courses</small></div><div class="stat-card"><span class="stat-icon orange">✓</span><span>Account role</span><strong class="role-value">Trainer</strong><small>Manage your learning content</small></div></section><?php foreach($errors as $err): ?><div class="alert error"><?= e($err) ?></div><?php endforeach; ?>
<section class="section dashboard-section" id="createCourse"><div class="section-heading"><div><span class="eyebrow">COURSE BUILDER</span><h2>Create a course</h2></div></div><div class="panel"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create_course"><label>Course title<input name="title" required placeholder="e.g. Introduction to Web Development"></label><label>Category<select name="category"><option>Technology</option><option>Programming</option><option>Data Science</option><option>Artificial Intelligence</option><option>Professional Skills</option><option>General</option></select></label><label>Card icon<input name="icon" maxlength="8" value="✦" placeholder="💻"></label><label>Visibility<select name="status"><option value="draft">Save as draft</option><option value="published">Publish course</option></select></label><label class="full-field">Course description<textarea name="description" rows="4" required placeholder="Describe the course and what learners can expect..."></textarea></label><div class="full-field"><button class="btn btn-primary">Save course →</button></div></form></div></section>
<section class="section dashboard-section"><div class="section-heading"><div><span class="eyebrow">YOUR CONTENT</span><h2>Manage courses</h2></div></div><?php if($courses): ?><div class="table-wrap"><table><thead><tr><th>Course</th><th>Category</th><th>Status</th><th>Enrollments</th><th>Manage</th></tr></thead><tbody><?php foreach($courses as $c): $s=db()->prepare('SELECT COUNT(*) FROM enrollments WHERE course_id=?');$s->execute([$c['id']]);$n=$s->fetchColumn(); ?><tr><td><b><?= e($c['title']) ?></b><?php if($u['role']==='admin'&&!empty($c['trainer_name'])): ?><small>by <?= e($c['trainer_name']) ?></small><?php endif; ?></td><td><?= e($c['category']) ?></td><td><span class="status-pill <?= e($c['status']) ?>"><?= e(ucfirst($c['status'])) ?></span></td><td><?= (int)$n ?></td><td><a href="course.php?id=<?= (int)$c['id'] ?>">View</a> · <a href="#contentTools">Add content</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><h3>No courses yet</h3><p>Create your first course using the form above.</p></div><?php endif; ?></section>
<section class="section dashboard-section" id="contentTools"><div class="section-heading"><div><span class="eyebrow">LEARNING MATERIALS</span><h2>Add course content</h2></div></div><div class="two-panels"><div class="panel"><h3>Share a resource</h3><p class="muted">Add a video, reading link or external study resource.</p><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add_resource"><label>Course<select name="course_id" required><?php foreach($courses as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['title']) ?></option><?php endforeach; ?></select></label><label>Resource title<input name="resource_title" required placeholder="e.g. HTML basics video"></label><label>Resource type<select name="resource_type"><option>Link</option><option>Video</option><option>Reading</option><option>Documentation</option></select></label><label>URL<input type="url" name="url" required placeholder="https://..."></label><button class="btn btn-primary">Add resource →</button></form></div><div class="panel"><h3>Create an assessment</h3><p class="muted">Set up an assessment shell. Add questions next.</p><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add_assessment"><label>Course<select name="course_id" required><?php foreach($courses as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['title']) ?></option><?php endforeach; ?></select></label><label>Assessment title<input name="assessment_title" required placeholder="e.g. Module 1 quiz"></label><label>Total marks<input type="number" name="total_marks" min="1" value="10" required></label><button class="btn btn-primary">Create assessment →</button></form></div></div></section><?php require 'includes/footer.php'; ?>
